#include <cstdio>
#include <memory>
#include <vector>

int main() {
    int n = 0;
    if (std::scanf("%d", &n) != 1) return 1;
    if (n < 1 || n > 1000) return 1;
    auto data = std::make_unique<std::vector<long long>>();
    for (int i = 0; i < n; i++) {
        long long value = 0;
        if (std::scanf("%lld", &value) != 1) return 1;
        if (value < -10000 || value > 10000) return 1;
        data->push_back(value);
    }
    long long total = 0;
    for (long long value : *data) total += value;
    std::printf("%lld\n", total);
    return 0;
}
